package com.hmdp.ai.runtime.node;
import com.fasterxml.jackson.databind.node.TextNode;import com.hmdp.ai.domain.workflow.*;import org.springframework.stereotype.Component;import java.util.*;
@Component public class BranchNodeExecutor implements NodeExecutor {private final ConditionDslEvaluator evaluator;public BranchNodeExecutor(ConditionDslEvaluator e){evaluator=e;}public Set<WorkflowNodeType>supportedTypes(){return Collections.singleton(WorkflowNodeType.BRANCH);}public NodeExecutionResult execute(NodeExecutionContext c){for(WorkflowEdgeDefinition e:c.getOutgoingEdges())if(evaluator.evaluate(e.getConditionJson(),c.getVariables()))return NodeExecutionResult.success(new TextNode(e.getTargetNodeCode()),Collections.singletonList(e.getTargetNodeCode()),null);return NodeExecutionResult.failure("WORKFLOW_BRANCH_NO_MATCH",false);}}
